WITH FilteredDepartments AS (SELECT * FROM departments WHERE NOT (budget BETWEEN 2557000 AND 2706000 AND location = 'Singapore')), departments_stats AS (SELECT CASE WHEN budget >= 4301000 THEN 'high' WHEN budget >= 809000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget FROM FilteredDepartments GROUP BY CASE WHEN budget >= 4301000 THEN 'high' WHEN budget >= 809000 THEN 'mid' ELSE 'low' END) SELECT * FROM departments_stats ORDER BY total_budget ASC, budget_bucket ASC LIMIT 1;
